function isOnTopic(item) {
  // Thanh Niên trả tiêu đề còn nguyên thực thể HTML (&aacute;...), nên giải mã trước khi so.
  const named = {
    amp: "&", quot: '"', lt: "<", gt: ">", nbsp: " ", apos: "'",
    aacute: "á", agrave: "à", acirc: "â", atilde: "ã", eacute: "é", egrave: "è", ecirc: "ê",
    iacute: "í", igrave: "ì", oacute: "ó", ograve: "ò", ocirc: "ô", otilde: "õ",
    uacute: "ú", ugrave: "ù", yacute: "ý",
  };
  const decode = (s) =>
    String(s || "")
      .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
      .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
      .replace(/&([a-z]+);/gi, (m, n) => named[n.toLowerCase()] ?? m);
  // Bỏ dấu để từ khoá viết một lần, khớp cả khi tiêu đề dùng dấu khác nhau.
  const flat = (s) =>
    decode(s)
      .toLowerCase()
      .normalize("NFD")
      .replace(/[̀-ͯ]/g, "")
      .replace(/đ/g, "d");

  const title = flat(item.title);
  const text = title + " " + flat(item.summary);

  // Loại ngay khi có trong TIÊU ĐỀ: tin tri ân, quà tặng, chuyện người thầy (xúc động nhưng
  // không giúp học sinh/phụ huynh quyết định gì). Ngày 20/11 có thể xuất hiện trong phần
  // tóm tắt của tin tuyển sinh (hạn đăng ký) nên chỉ xét ở tiêu đề.
  const blockTitle = /\b(?:20\/11|ngay nha giao|nha giao|tri an|qua tang|boc tham|chuc mung|loi chuc|thay co|co giao|thay giao|ky niem|ngay hoi)\b/;
  // Loại khi có ở tiêu đề hoặc tóm tắt: sự cố, vụ việc, thời sự và tin ngoài giáo dục.
  const blockAny =
    /\b(?:bao luc|danh nhau|danh hoi dong|xam hai|tu vong|bat tinh|tai nan|duoi nuoc|ngo doc|tu tu|bi bat|khoi to|truy to|tam giam|ky luat|canh cao|bi chem|gia vang|thoi tiet|bong da|bong ro|u17|u23|world cup|clip|hot girl|nuoc nao|ho nhieu nhat|dong ho|hoang tu|ty phu|ti phu|gian lan|to giac|bao che|vi pham|sai pham|thanh tra|lua dao|tranh cai|buc xuc|phan no|scandal|bi phat|dinh chi|bi dieu tra|vu an|danh bac|ma tuy)\b/;
  if (blockTitle.test(title) || blockAny.test(text)) return false;

  // Phải chạm ít nhất một chủ đề cần: tuyển sinh/thi cử, chính sách, học tập, chọn ngành.
  const allow =
    /tuyen sinh|xet tuyen|tuyen thang|du tuyen|diem chuan|diem san|diem cong|diem thi|tot nghiep|ky thi|thi thpt|thi vao|vao lop|lop 1\b|lop 6|lop 9|lop 10|lop 12|thi danh gia|danh gia nang luc|danh gia tu duy|hoc ba|chuong trinh|sach giao khoa|quy che|quy dinh|thong tu|nghi dinh|du thao|de xuat|chinh sach|hoc phi|mien giam|hoc bong|tro cap|ho tro hoc|day them|hoc them|ielts|toefl|chung chi|ngoai ngu|du hoc|chon nganh|nganh hoc|dai hoc|cao dang|hoc sinh|phu huynh|sinh vien|nhan luc|viec lam|huong nghiep|phuong phap|on thi|de thi|mon thi|hoc tap|tu hoc|chuan dau ra|bo gd|bo giao duc|mon hoc|to hop mon|nghien cuu|khoa hoc|cong bo|sang che|giai thuong|giai nhat|huy chuong|olympic|thanh tich|xep hang|robot|tri tue nhan tao|cong nghe|chuyen doi so|hop tac dao tao|dao tao|thac si|tien si|nganh/;
  return allow.test(text);
}

function sourceInfo(link) {
  const known = [
    [/(^|\.)uet\.vnu\.edu\.vn$/, "Trường ĐH Công nghệ - ĐHQGHN", 0],
    [/(^|\.)ulis\.vnu\.edu\.vn$/, "Trường ĐH Ngoại ngữ - ĐHQGHN", 0],
    [/(^|\.)law\.vnu\.edu\.vn$/, "Trường ĐH Luật - ĐHQGHN", 0],
    [/(^|\.)vju\.ac\.vn$/, "Trường ĐH Việt Nhật - ĐHQGHN", 0],
    [/(^|\.)vnu\.edu\.vn$/, "Đại học Quốc gia Hà Nội", 0],
    [/(^|\.)hcmus\.edu\.vn$/, "Trường ĐH Khoa học Tự nhiên - ĐHQG-HCM", 0],
    [/(^|\.)vnuhcm\.edu\.vn$/, "Đại học Quốc gia TP.HCM", 0],
    [/(^|\.)thanhnien\.vn$/, "Thanh Niên", 1],
    [/(^|\.)baochinhphu\.vn$/, "Báo điện tử Chính phủ", 2],
    [/(^|\.)vtv\.vn$/, "VTV", 2],
    [/(^|\.)tuoitre\.vn$/, "Tuổi Trẻ", 3],
  ];
  const host = (String(link).match(/^https?:\/\/(?:www\.)?([^/:?#]+)/) || [])[1];
  if (!host) return { name: "Nguồn khác", rank: 9 };
  const hit = known.find(([re]) => re.test(host.toLowerCase()));
  return hit ? { name: hit[1], rank: hit[2] } : { name: host, rank: 9 };
}

function findImage(input) {
  const { enclosure, content, meta, link } = input || {};
  const trusted = /(^|\.)(vnu\.edu\.vn|vju\.ac\.vn|hcmus\.edu\.vn|cdneverest\.net|thanhnien\.vn|cdnchinhphu\.vn|vtv\.vn|tuoitre\.vn)$/;
  const origin = (String(link || "").match(/^(https:\/\/[^/?#]+)/) || [])[1] || "";

  const clean = (raw) => {
    let u = String(raw || "").trim().replace(/&amp;|&#0?38;/g, "&");
    if (u.startsWith("//")) u = "https:" + u;
    else if (u.startsWith("/") && origin) u = origin + u;
    if (!/^https:\/\/[^\s()<>"'\\]+$/.test(u) || u.length > 500) return "";
    const host = (u.match(/^https:\/\/([^/:?#]+)/) || [])[1] || "";
    if (!trusted.test(host.toLowerCase())) return "";
    // Ảnh logo/mặc định của site và ảnh vector không phải ảnh của bài.
    if (/logo|favicon|default|placeholder|no-?image/i.test(u) || /\.svg(\?|$)/i.test(u)) return "";
    return u;
  };

  const candidates = [];
  for (const tag of String(meta || "").match(/<meta\b[^>]*>/gi) || []) {
    if (!/(og:image|twitter:image)/i.test(tag)) continue;
    const m = tag.match(/\bcontent\s*=\s*["']([^"']+)["']/i);
    if (m) candidates.push(m[1]);
  }
  if (enclosure && enclosure.url && (!enclosure.type || /^image\//i.test(enclosure.type))) candidates.push(enclosure.url);
  for (const tag of String(content || "").match(/<img\b[^>]*>/gi) || []) {
    const m = tag.match(/\bsrc\s*=\s*["']([^"']+)["']/i);
    if (m) candidates.push(m[1]);
  }

  for (const c of candidates) {
    const ok = clean(c);
    if (ok) return ok;
  }
  return "";
}

const cfg = $('Cài đặt').first().json;
const state = parseState($('Đọc trạng thái').first().json.stdout);
const feed = $input.all().map((i) => i.json).filter((j) => j && j.link && j.title)
  .filter((j) => isOnTopic({ title: j.title, summary: j.contentSnippet || j.content }))
  .map((j) => {
    const info = sourceInfo(j.link);
    return {
      title: String(j.title),
      link: String(j.link),
      source: info.name,
      rank: info.rank,
      summary: String(j.contentSnippet || j.content || "").slice(0, 1000),
      isoDate: j.isoDate || j.pubDate || "",
      rssImage: findImage({ enclosure: j.enclosure, content: j.content, link: j.link }),
    };
  });
const today = todayVN(new Date());
const { pick, markSeen } = pickNew(feed, state, { perRun: cfg.perRun, perDay: cfg.perDay, today, maxAgeDays: 30, nowMs: Date.now() });
if (!pick.length) return [{ json: { none: true, markSeen, today } }];
return pick.map((it, idx) => ({
  json: {
    ...it,
    promptB64: Buffer.from(buildPrompt(it), "utf8").toString("base64"),
    linkB64: Buffer.from(it.link, "utf8").toString("base64"),
    markSeen: idx === 0 ? markSeen : [],
    today,
  },
}));

function extractSessionCookie(setCookie) {
  const text = Array.isArray(setCookie) ? setCookie.join("\n") : String(setCookie ?? "");
  const match = text.match(/giasu_session=([^;,\s]+)/);
  return match ? `giasu_session=${match[1]}` : null;
}

const login = $input.first().json;
const cookie = extractSessionCookie(login.headers && login.headers["set-cookie"]);
if (!cookie) throw new Error("Đăng nhập web không trả cookie phiên (kiểm tra credential News Bot Login)");
return $('Chọn tin mới').all().map((i) => ({ json: { ...i.json, cookie } }));

function parseClaudeOutput(raw) {
  const objectsIn = (text) => {
    const found = [];
    for (let start = text.indexOf("{"); start >= 0; start = text.indexOf("{", start + 1)) {
      let depth = 0;
      let inString = false;
      let escaped = false;
      for (let i = start; i < text.length; i++) {
        const c = text[i];
        if (inString) {
          if (escaped) escaped = false;
          else if (c === "\\") escaped = true;
          else if (c === '"') inString = false;
          continue;
        }
        if (c === '"') inString = true;
        else if (c === "{") depth += 1;
        else if (c === "}") {
          depth -= 1;
          if (depth === 0) {
            try {
              found.push(JSON.parse(text.slice(start, i + 1)));
            } catch {
              // không phải JSON hợp lệ, thử vị trí { kế tiếp
            }
            break;
          }
        }
      }
    }
    return found;
  };

  let text = String(raw ?? "");
  try {
    const outer = JSON.parse(text);
    if (outer && typeof outer === "object" && typeof outer.result === "string" && !("skip" in outer)) {
      if (outer.is_error) return null;
      text = outer.result;
    }
  } catch {
    // không phải bao JSON của claude -p, coi là chữ thường
  }

  for (const o of objectsIn(text)) {
    if (!o || typeof o !== "object" || typeof o.skip !== "boolean") continue;
    if (o.skip) return { skip: true, reason: String(o.reason ?? "") };
    if ([o.title, o.summary, o.body].every((v) => typeof v === "string")) {
      return { skip: false, title: o.title, summary: o.summary, body: o.body, topic: typeof o.topic === "string" ? o.topic : "" };
    }
  }
  return null;
}

function normalizeDraft(d) {
  const clean = (s) =>
    String(s)
      .replace(/\*\*/g, "")
      .replace(/`/g, "")
      .replace(/^#{1,6}[ \t]*/gm, "")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  // Chủ đề thiếu hoặc lạ thì xếp vào "study" chứ không bỏ bài.
  const topic = String(d.topic ?? "").trim().toLowerCase();
  return {
    title: clean(d.title),
    summary: clean(d.summary),
    body: clean(d.body),
    topic: ["admissions", "policy", "study"].includes(topic) ? topic : "study",
  };
}

function validateDraft(d, item) {
  const reasons = [];
  if (d.title.length < 1 || d.title.length > 160) reasons.push("title phải từ 1 đến 160 ký tự");
  if (d.summary.length < 1 || d.summary.length > 500) reasons.push("summary phải từ 1 đến 500 ký tự");
  if (d.body.length < 600) reasons.push("body ngắn hơn 600 ký tự");
  if (d.body.length > 30000) reasons.push("body dài hơn 30000 ký tự");
  const lastLine = d.body.trim().split("\n").at(-1).trim();
  if (!lastLine.startsWith("Nguồn:") || !lastLine.includes(item.link)) {
    reasons.push("dòng cuối phải bắt đầu bằng Nguồn: và chứa link bài gốc");
  }
  return { ok: reasons.length === 0, reasons };
}

function buildPostBody(d, image, item) {
  // Ảnh bìa và nguồn đi bằng trường riêng; body chỉ còn chữ bài (không dòng ảnh, không dòng "Nguồn:").
  const alt = String(d.title).replace(/[\[\]]/g, "").trim();
  const lines = String(d.body).split("\n");
  let end = lines.length;
  while (end > 0 && !lines[end - 1].trim()) end -= 1;
  const found = end > 0 ? lines[end - 1].match(/^Nguồn:\s*(.+?)\s+-\s+(https?:\/\/\S+)\s*$/) : null;
  let source = item && item.link ? { name: String(item.source || ""), url: item.link } : null;
  let body = d.body;
  if (found) {
    if (!source) source = { name: found[1].trim(), url: found[2] };
    body = lines.slice(0, end - 1).join("\n").replace(/\n+$/, "");
  }
  const hasImage = image && image.url;
  return {
    title: d.title,
    summary: d.summary,
    body,
    topic: ["admissions", "policy", "study"].includes(d.topic) ? d.topic : "study",
    origin: "auto",
    cover_url: hasImage ? image.url : "",
    cover_alt: hasImage ? alt : "",
    cover_credit: hasImage ? String(image.credit || "") : "",
    source_name: source ? source.name : "",
    source_url: source ? source.url : "",
    published: false,
  };
}

function findImage(input) {
  const { enclosure, content, meta, link } = input || {};
  const trusted = /(^|\.)(vnu\.edu\.vn|vju\.ac\.vn|hcmus\.edu\.vn|cdneverest\.net|thanhnien\.vn|cdnchinhphu\.vn|vtv\.vn|tuoitre\.vn)$/;
  const origin = (String(link || "").match(/^(https:\/\/[^/?#]+)/) || [])[1] || "";

  const clean = (raw) => {
    let u = String(raw || "").trim().replace(/&amp;|&#0?38;/g, "&");
    if (u.startsWith("//")) u = "https:" + u;
    else if (u.startsWith("/") && origin) u = origin + u;
    if (!/^https:\/\/[^\s()<>"'\\]+$/.test(u) || u.length > 500) return "";
    const host = (u.match(/^https:\/\/([^/:?#]+)/) || [])[1] || "";
    if (!trusted.test(host.toLowerCase())) return "";
    // Ảnh logo/mặc định của site và ảnh vector không phải ảnh của bài.
    if (/logo|favicon|default|placeholder|no-?image/i.test(u) || /\.svg(\?|$)/i.test(u)) return "";
    return u;
  };

  const candidates = [];
  for (const tag of String(meta || "").match(/<meta\b[^>]*>/gi) || []) {
    if (!/(og:image|twitter:image)/i.test(tag)) continue;
    const m = tag.match(/\bcontent\s*=\s*["']([^"']+)["']/i);
    if (m) candidates.push(m[1]);
  }
  if (enclosure && enclosure.url && (!enclosure.type || /^image\//i.test(enclosure.type))) candidates.push(enclosure.url);
  for (const tag of String(content || "").match(/<img\b[^>]*>/gi) || []) {
    const m = tag.match(/\bsrc\s*=\s*["']([^"']+)["']/i);
    if (m) candidates.push(m[1]);
  }

  for (const c of candidates) {
    const ok = clean(c);
    if (ok) return ok;
  }
  return "";
}

